Translate("deDE", "city-of-dalaran-dungeon", {
	title = "Dungeon der Stadt Dalaran",
	aliases = { "die unruhigen Hallen von Dalaran" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Unter dem strahlenden Antlitz der wiederaufgebauten {link:city-of-dalaran}Stadt Dalaran{/link} liegt eine Stadt, die ihre Herren nicht mehr ganz beherrschen. Die Magier errichteten {link:dalaran}Dalaran{/link} hinter ihrer großen Barriere neu, und als die Barriere fiel, öffneten sie ihre Tore, als sei alles in Ordnung. Das ist es nicht. An manchen Orten ist die wiederhergestellte Stadt der Kontrolle der {link:kirin-tor}Kirin Tor{/link} entglitten. Zauber wenden sich gegen jene, die sie wirken, Konstrukte, die zum Dienen geschaffen wurden, wandeln frei umher, rohes Mana hat Gestalt und Hunger angenommen, und etwas Dämonisches hat Wurzeln geschlagen, wo kein Dämon sein dürfte. Die Kirin Tor brauchen Hilfe, und sie sind zu stolz, laut darum zu bitten.]=],
		},
		{
			title = "Ursprünge",
			text = [=[{link:dalaran}Dalaran{/link} wurde schon einmal zerstört. Im {link:third-war}Dritten Krieg{/link} vernichtete {link:archimonde}Archimonde{/link} die Stadt mit einem einzigen Zauber, und die Überlebenden verbrachten Jahre damit, sie im Geheimen wiederaufzubauen. Ein solches Werk war nicht ohne gewaltige Ströme {link:arcane-magic}arkaner Magie{/link} zu vollbringen, ohne Schutzzauber über Schutzzauber und ohne Diener, die durch Verzauberung gebunden waren. Wie viel von dieser alten Macht noch in den Steinen verweilt und wie viel vom Schatten des Dämonenfürsten, kann niemand außerhalb des Ordens sagen. Die Unruhen im Inneren begannen, bevor die Barriere fiel. Ob sie ihren Fall verursachten, hat noch niemand gesagt.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Ermittler der {link:kirin-tor}Kirin Tor{/link} sprechen von einer Störung, die mit jedem Tag schlimmer wird, und von Erkenntnissen aus einem Pylon, die sie noch nicht erklären können. Ihre Befehle lauten, die Stadt ruhig zu halten. Unterdessen haben sich die Hallen darunter mit Dingen gefüllt, die nicht sein sollten. Darunter sind ein Ort namens {link:fel-grove}Teufelshain{/link}, wo {link:fel-magic}Teufelsmagie{/link} in lebendes Holz gesickert ist, und umherirrende Schemen der Toten.]=],
		},
		{
			title = "Die hier hausen",
			text = [=[• {b}Die {link:arcane-anomaly}Arkane Anomalie{/link}.{/b} Magie, die aus ihrem Muster ausgebrochen ist.
• {b}Der Teufelsuralte.{/b} Ein großes Wesen aus Holz und Wurzel, verderbt durch {link:fel-magic}Teufelsmagie{/link}.
• {b}Der {link:mana-devourer}Manaverschlinger{/link}, das {link:mana-elemental}Manaelementar{/link} und das {link:mana-wraith}Managespenst{/link}.{/b} Geschöpfe aus rohem Mana, geboren aus der überfließenden Macht der Stadt.
• {b}Der Instabile {link:the-night-watch}Wächter{/link}.{/b} Ein Wächterkonstrukt, das nicht mehr gehorcht.
• {b}Der {link:shade-of-the-archmage}Schemen des Erzmagiers{/link}.{/b} Der Geist eines von Dalarans eigenen Magiern.
• {b}{link:lyn-the-ignored}Lyn the Ignored{/link}.{/b} Eine Gestalt, deren Geschichte sich niemand anzuhören bemüht hat.
• {b}{link:atrexis-the-grave-knight}Atrexis the Grave Knight{/link}.{/b} Ein Ritter des Grabes, gekommen in {link:city-of-dalaran}die Stadt der Magier{/link}.]=],
		},
	},
})

Translate("deDE", "fel-grove", {
	title = "Teufelshain",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Teufelshain liegt in den unruhigen Hallen von {link:dalaran}Dalaran{/link}. Sein Name sagt, was die Magier am wenigsten hören wollen: dass {link:fel-magic}Teufelsmagie{/link}, die Macht der {link:burning-legion}Brennenden Legion{/link}, in der Stadt der {link:kirin-tor}Kirin Tor{/link} eine Heimat gefunden und wachsende Dinge berührt hat. Wie ein Hain im Herzen Dalarans wachsen konnte und wie er verseucht wurde, erklärt noch keine Aufzeichnung. Er mag einer der Orte sein, an denen die dämonische Energie, die die Stadt heimsucht, am stärksten ist.]=],
		},
	},
})

Translate("deDE", "arcane-anomaly", {
	title = "Arkane Anomalie",
	subtitle = "Entfesselte Magie",
	hint = [=[Stellt Euch dem lebenden Knoten aus Magie, der sich in den Hallen von Dalaran befreit hat.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Arkane Anomalie ist Magie, die ihre Gestalt verloren und einen eigenen Willen gefunden hat. Die {link:kirin-tor}Kirin Tor{/link} bauten ihre Stadt mit Verzauberung über Verzauberung wieder auf, und nicht alle dieser Zauber haben gehalten. Manche sind vom Weg abgekommen. Dieser ist zu etwas herangewachsen, das sich bewegt und zuschlägt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Anomalie ist das deutlichste Zeichen dafür, was in {link:dalaran}Dalaran{/link} schiefgegangen ist. Die eigene Macht der Stadt hat begonnen, sich gegen sie zu wenden.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch sagt keine Aufzeichnung, welcher Zauber die Anomalie hervorbrachte oder wie lange sie schon durch die Stadt irrt.]=],
		},
	},
})

Translate("deDE", "fel-ancient", {
	title = "Teufelsuralter",
	subtitle = "Der verderbte Wächter",
	hint = [=[Stellt Euch dem verseuchten Riesen aus Wurzel und Holz in den unruhigen Hallen von Dalaran.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Teufelsuralte trägt den Namen der Uralten, der großen Geister aus Holz und Wurzel, die die Wälder der Welt bewachen. Dieser wurde von {link:fel-magic}Teufelsmagie{/link} berührt. Es ist ein seltsamer Fund in einer Stadt menschlicher Magier, und ein gefährlicher. Wo Teufelsmagie Wurzeln schlägt, ist die {link:burning-legion}Brennende Legion{/link} selten weit.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Teufelsuralte gibt der dämonischen Energie Gestalt, die die {link:kirin-tor}Kirin Tor{/link} in ihren Straßen gespürt haben.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch sagt keine Aufzeichnung, wie ein Uralter nach {link:dalaran}Dalaran{/link} kam oder was ihn verderbte.]=],
		},
	},
})

Translate("deDE", "mana-devourer", {
	title = "Manaverschlinger",
	subtitle = "Der Hunger der Stadt",
	hint = [=[Stellt Euch dem Geschöpf, das sich von der Magie Dalarans nährt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Manaverschlinger nährt sich von Magie. {link:dalaran}Dalaran{/link} ist eine aus Zaubern erbaute Stadt, und ihre Steine und Schutzzauber sind schwer von Mana. Für ein solches Geschöpf ist die Stadt ein Festmahl. Wohin es auch geht, werden die Verzauberungen der Magier schwächer, und es wird stärker.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:chol-aruk}Der Verschlinger{/link} ist eines von drei Geschöpfen aus Mana, die die Stadt heimsuchen. Sein Hunger bedroht genau die Magie, die das neue {link:dalaran}Dalaran{/link} zusammenhält.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch sagt keine Aufzeichnung, woher der Verschlinger kam oder ob er von der Stadt angezogen oder in ihr geboren wurde.]=],
		},
	},
})

Translate("deDE", "mana-elemental", {
	title = "Manaelementar",
	subtitle = "Rohe Magie, die Gestalt annahm",
	hint = [=[Stellt Euch dem Wesen aus rohem Mana, das sich in den Hallen von Dalaran regt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Manaelementar ist rohes Mana, das Gestalt angenommen hat. Die Magier von {link:dalaran}Dalaran{/link} haben schon immer Elementare an ihren Dienst gebunden, und in den Jahren des Wiederaufbaus waren ihre Diener zahlreich. Dieses dient niemandem. Ob es einst gebunden war und sich befreite oder ob die überfließende Macht der Stadt es ins Dasein rief, haben die {link:kirin-tor}Kirin Tor{/link} nicht gesagt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Das Manaelementar ist eines von drei Geschöpfen aus Mana, die die Stadt heimsuchen.]=],
		},
		{ title = "Unaufgezeichnet", text = "Noch erzählt keine Aufzeichnung seine Geschichte." },
	},
})

Translate("deDE", "mana-wraith", {
	title = "Managespenst",
	subtitle = "Das ruhelose Mana",
	hint = [=[Stellt Euch dem Gespenst aus Mana, das die Hallen von Dalaran heimsucht.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Managespenst treibt durch {link:city-of-dalaran-dungeon}die unruhigen Hallen von Dalaran{/link} wie ein Geist aus Magie. Sein Name verbindet zwei Dinge, die die {link:kirin-tor}Kirin Tor{/link} fürchten: die rohe Macht, über die sie gebieten, und die ruhelosen Toten. Es mag ein Geist sein, der sich von Mana nährte, bis Mana alles war, was von ihm übrig blieb. Es mag etwas Seltsameres sein.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Das Managespenst ist eines von drei Geschöpfen aus Mana, die die Stadt heimsuchen.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch sagt keine Aufzeichnung, was das Gespenst zuvor war, falls es je etwas anderes war.]=],
		},
	},
})

Translate("deDE", "unstable-sentinel", {
	title = "Instabiler Wächter",
	subtitle = "Der Wächter, der nicht gehorcht",
	hint = [=[Stellt Euch dem Wächterkonstrukt, das sich der Kontrolle seiner Herren entzogen hat.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Instabile {link:the-night-watch}Wächter{/link} wurde geschaffen, um zu bewachen. Die {link:kirin-tor}Kirin Tor{/link} füllen ihre Stadt mit arkanen Posten, die ohne Rast Wache halten. Dieser Wächter antwortet ihnen nicht mehr. Seine Verzauberungen sind instabil geworden, und ein Wächter, der Freund und Feind nicht unterscheiden kann, ist gefährlicher als jeder Dieb.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der {link:the-night-watch}Wächter{/link} ist eines der Konstrukte, die sich in der wiederhergestellten Stadt von ihren Fesseln gelöst haben.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch sagt keine Aufzeichnung, was der {link:the-night-watch}Wächter{/link} einst bewachte.]=],
		},
	},
})

Translate("deDE", "shade-of-the-archmage", {
	title = "Schemen des Erzmagiers",
	subtitle = "Ein Geist der Kirin Tor",
	hint = [=[Stellt Euch dem Geist eines Erzmagiers, der noch immer durch die Hallen von Dalaran wandelt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schemen des Erzmagiers ist der Geist eines von Dalarans eigenen Magiern. Viele der {link:kirin-tor}Kirin Tor{/link} starben, als die {link:scourge}Geißel{/link} und {link:archimonde}Archimonde{/link} im {link:third-war}Dritten Krieg{/link} über die Stadt herfielen. Dieser hat keine Ruhe gefunden. Er wandelt durch die Hallen der Stadt, der er diente, und er heißt die Lebenden nicht willkommen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Schemen erinnert daran, dass {link:dalaran}Dalaran{/link} auf den Gräbern seiner Verteidiger wiederaufgebaut wurde.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch nennt keine Aufzeichnung den Erzmagier, der der Schemen einst war, oder sagt, warum der Geist nicht ruhen kann. Die {link:kirin-tor}Kirin Tor{/link} haben es nicht gesagt, falls sie es wissen.]=],
		},
	},
})

Translate("deDE", "lyn-the-ignored", {
	title = "Lyn the Ignored",
	subtitle = "Ungehört",
	hint = [=[Sucht jene Gestalt in Dalaran, der nie jemand Gehör geschenkt hat.]=],
	allegiance = "Keine",
	aliases = { "Lyn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lyn the Ignored ist unter einem Namen bekannt, der wie eine Klage klingt. Es ist ein seltsamer Name in {link:dalaran}Dalaran{/link}, einer Stadt stolzer Magier, in der Rang und Gelehrsamkeit alles zählen. Wer Lyn auch war, übergangen wird Lyn jetzt nicht mehr. In den unruhigen Hallen unter der wiederaufgebauten Stadt ist Lyn zu einer der Mächte geworden, die die {link:kirin-tor}Kirin Tor{/link} nicht länger übersehen können.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lyn ist eines der seltsameren Rätsel der wiederhergestellten Stadt. Allein der Name deutet auf eine Geschichte hin, die die {link:kirin-tor}Kirin Tor{/link} nicht erzählt haben.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch erzählt keine Aufzeichnung, wer Lyn war, wer Lyn überging oder warum. Alles in diesem Eintrag jenseits des Namens ist eine Deutung dieses Namens.]=],
		},
	},
})

Translate("deDE", "atrexis-the-grave-knight", {
	title = "Atrexis the Grave Knight",
	subtitle = "Ritter des Grabes",
	hint = [=[Stellt Euch dem Ritter des Grabes, der in die Hallen von Dalaran gekommen ist.]=],
	allegiance = "Keine",
	aliases = { "Atrexis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Atrexis wird der Grabritter genannt. Der Name gehört den Toten, nicht den Magiern, und er klingt finster in {link:dalaran}Dalaran{/link}. Die Stadt hat schon früher Ritter des Todes gekannt: Die {link:scourge}Geißel{/link}, die sie zerstörte, marschierte unter Champions, die sich aus dem Grab erhoben hatten. Was Atrexis ist und wem Atrexis dient, haben die {link:kirin-tor}Kirin Tor{/link} nicht gesagt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Atrexis ist die kriegerischste der Mächte in der unruhigen Stadt, ein Ritter, wo andere Zauber und Geister sind.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Noch erzählt keine Aufzeichnung die Geschichte von Atrexis oder wie ein Grabritter dazu kam, unter den Magiern zu wandeln.]=],
		},
	},
})
